insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('cementing', 'advanced', 'module', 'm01-why-mud-removal-decides-it', 1, 'Why does cement take the wide side of an eccentric annulus?', '["Because the cement is denser than the mud it displaces.", "Because resistance in a slot goes roughly as the inverse cube of the gap, so a half-width side offers eight times as much.", "Because the casing lies on the low side, and the cement is pumped from above so it reaches the top of the annulus first.", "Because the narrow side is where the cuttings bed is, and a bed of solids is harder to displace than a fluid column."]'::jsonb, 1, 'The mud on the narrow side stays where it is.'),
  ('cementing', 'advanced', 'module', 'm01-why-mud-removal-decides-it', 2, 'What does a mud channel look like on the job records?', '["Nothing at all: the volume balance, the plug bump and the pressure record are all unaffected by it.", "A loss of returns during the displacement phase.", "A pressure test failure, since a channel is a flow path around the barrier and the test would find it before drilling ahead.", "A shortfall in the returns volume, since the mud that was not displaced never came back out of the annulus at surface."]'::jsonb, 0, 'A bond log sees it, if one is run and if the channel is on the side the tool looks at.'),
  ('cementing', 'advanced', 'module', 'm01-why-mud-removal-decides-it', 3, 'What are the three things that fix a channel?', '["A higher pump rate, a bigger spacer and more cement.", "Centralization, a longer shoe track and a lower top of cement, all three of which reduce the length of the exposed annulus.", "Better centralization, rotating or reciprocating the casing, and a spacer designed for the displacement regime.", "Centralization, casing movement and fluid design, and this course quantifies only the first."]'::jsonb, 3, 'A well-centralized job with the casing sitting still and a poor spacer can still channel.'),
  ('cementing', 'advanced', 'module', 'm01-why-mud-removal-decides-it', 4, 'Define standoff.', '["The offset of the pipe divided by the clearance.", "The ratio of the narrow gap to the wide gap, which is one for a centred pipe and zero for one touching the wall.", "The narrow side gap divided by the concentric clearance, running from zero at the wall to one at centre.", "The fraction of the annular circumference that the cement displaces cleanly, which is what the API target refers to."]'::jsonb, 2, 'It is one less the eccentricity, and confusing the two is a real error.'),
  ('cementing', 'advanced', 'module', 'm01-why-mud-removal-decides-it', 5, 'What is the clearance in this well''s open hole section?', '["0.021348699999999998 m, the cased section value.", "0.019049999999999997 m, half the difference between the 8-1/2 inch bit and the 7 inch casing.", "0.0381 m, the full difference between the bit size of 0.2159 m and the casing outside diameter of 0.1778 m.", "0.021624664102633667 m, which is the value after the 15 percent open hole excess has been applied to it."]'::jsonb, 1, 'Nineteen millimetres is the whole distance the pipe has to move to be touching the wall.'),
  ('cementing', 'advanced', 'module', 'm01-why-mud-removal-decides-it', 6, 'Which bore does the standoff calculation measure the clearance in?', '["The nominal one, because the engine runs the annulus rows with an excess of zero.", "The washed-out one, at 15 percent excess.", "Whichever is smaller, so that the calculation is conservative regardless of how much the hole has actually washed out.", "The drift diameter of the previous casing, since that is the smallest restriction the centralizer has to pass through."]'::jsonb, 0, 'It is a deliberate choice and it is not documented in the function signature.'),
  ('cementing', 'advanced', 'module', 'm01-why-mud-removal-decides-it', 7, 'How many standoff numbers does each interval of the profile carry?', '["One, the reported minimum for that interval.", "Two, the value at each of the two centralizers bounding the interval, which differ if the inclination changes across it.", "Three, of which the reported one is always the mid-span value because the sag is never negative.", "Three: the value at a centralizer, the value at mid span, and the smaller of the two."]'::jsonb, 3, 'The reported one is the smaller, and on both of this course''s wells it is always the mid-span value.'),
  ('cementing', 'advanced', 'module', 'm01-why-mud-removal-decides-it', 8, 'Where does the API 67 percent target come from?', '["A measurement of displacement efficiency in a flow loop.", "The point at which the narrow side gap becomes large enough for turbulent displacement to be achieved at a realistic rate.", "A convention from API Specification 10D, chosen because a threshold is useful, and it is not a cliff.", "The eccentricity at which the flow resistance ratio between the two sides of the annulus falls below two to one."]'::jsonb, 2, 'Nothing changes at two thirds, and the displacement efficiency falls off smoothly.'),
  ('cementing', 'advanced', 'module', 'm01-why-mud-removal-decides-it', 9, 'The number 0.67 appears in this engine for two unrelated purposes. What are they?', '["The target and the default mid-span sag limit.", "The acceptance target for the checklist, and the standoff at which a bow spring''s restoring force is quoted.", "The acceptance target and the default rigid blade ratio, which the engine assumes when no blade diameter is supplied to it.", "The target and the fraction of the clearance a bow spring can take up before it takes a permanent set from overloading."]'::jsonb, 1, 'The engine exposes the second one separately, so the two could be decoupled.'),
  ('cementing', 'advanced', 'module', 'm01-why-mud-removal-decides-it', 10, 'The two wells reach 0.742357202445576 and 0.599178961025609 at the same spacing. What differs?', '["Only the inclination: one reaches 40 degrees and the other 90.", "The casing weight and the mud density.", "The clearance, since the horizontal well''s open hole section is drilled with a smaller bit than the slant well''s is.", "The centralizer, since a horizontal well needs a stiffer bow spring and the two wells are run with different ones."]'::jsonb, 0, 'Same casing, same hole sizes, same centralizer, same mud.'),
  ('cementing', 'advanced', 'module', 'm01-why-mud-removal-decides-it', 11, 'What flows through a mud channel?', '["Only gas, which is why it appears as casing pressure.", "Cement, slowly, as the channel dehydrates and the surrounding sheath shrinks away from the pipe over the following months.", "Formation water, gas or injected fluid, depending on what the channel connects and in which direction the pressure runs.", "Formation water into a hydrocarbon zone, gas up the annulus, or injected fluid out of zone."]'::jsonb, 3, 'Gas up the annulus appears at surface as sustained casing pressure.'),
  ('cementing', 'advanced', 'module', 'm01-why-mud-removal-decides-it', 12, 'How long does a channel take to show itself?', '["Immediately, at the pressure test after the job.", "Within days, since the mud in the channel dehydrates quickly once the cement around it sets and the path opens up.", "Months to decades, which is what makes it the expensive failure.", "At the next casing shoe leak-off test, which is the first time the sheath is loaded along any part of its length."]'::jsonb, 2, 'By the time it appears the well is producing and the remedy is a remedial squeeze.'),
  ('cementing', 'advanced', 'module', 'm01-why-mud-removal-decides-it', 13, 'What does a pressure test after cementing NOT catch?', '["A leaking float collar.", "A channel along the sheath, because the test loads the casing and the shoe and not the sheath''s length.", "A shoe track that was displaced out into the annulus, since that would show up as a low leak-off at the shoe afterwards.", "A top of cement short of its target, which is what a temperature log run after the job is intended to find instead."]'::jsonb, 1, 'A channel from 1400 m to 2800 m is not tested by anything a rig does after the cement sets.'),
  ('cementing', 'advanced', 'module', 'm01-why-mud-removal-decides-it', 14, 'Why is the standoff arithmetic worth doing?', '["Because twenty minutes of it beats a remedial squeeze on a producing well by a factor of about a thousand in cost.", "Because it is required by the API specification.", "Because it is the only one of the three mud removal levers that can be verified afterwards by a cement bond log.", "Because it guarantees the job will isolate, provided the minimum standoff clears the API sixty seven percent target."]'::jsonb, 0, 'It is one of the few places in drilling engineering where the analysis is unambiguously cheaper than the consequence.'),
  ('cementing', 'advanced', 'module', 'm01-why-mud-removal-decides-it', 15, 'What is the honest limit of the standoff argument?', '["It applies only to bow spring centralizers.", "It assumes the hole is round, which a breakout makes untrue exactly where the standoff calculation matters the most.", "It is one of three levers and the model has only that one, so it is necessary and not sufficient.", "It uses the nominal bore rather than the washed-out one, so every number it reports is optimistic by about thirteen percent."]'::jsonb, 2, 'A job at 80 percent standoff pumped with the casing stationary behind a poor spacer can still channel.'),
  ('cementing', 'advanced', 'module', 'm02-the-centralizer', 1, 'What kind of device is a bow spring centralizer?', '["A spacer, fixed by its outside diameter.", "A spring, so the standoff it achieves depends on the load, the spacing and the hole angle.", "A rigid body machined to a stated diameter, which is what allows it to be run through a restriction smaller than the hole.", "A friction device, which grips the casing wall and holds the string at whatever position it was landed in."]'::jsonb, 1, 'It can be pushed to zero standoff by a large enough load, and it passes through restrictions.'),
  ('cementing', 'advanced', 'module', 'm02-the-centralizer', 2, 'And the other family of centralizer, the one machined to a fixed size?', '["A spacer, whose standoff is a ratio of diameters with no load, spacing or inclination in it.", "A spring with a much higher restoring force.", "A device whose standoff depends on the clearance, since a larger hole gives it more room to expand into and grip against.", "A stabiliser, whose blades cut into the wall and hold the casing at a fixed position regardless of the lateral load."]'::jsonb, 0, 'It cannot be pushed further in, and it cannot pass a restriction smaller than its blade.'),
  ('cementing', 'advanced', 'module', 'm02-the-centralizer', 3, 'What does the engine assume if no rigid blade diameter is given?', '["That the caller meant a bow spring instead.", "Sixty seven percent standoff, which is the API target and therefore the natural default for a device sized to reach it.", "Ten millimetres under the bore of that row, which on this well''s open hole gives about seventy four percent before any sag.", "Ten millimetres under the bore, which is a generous assumption and a silent one."]'::jsonb, 3, 'A real rigid centralizer for an 8-1/2 inch hole would typically be smaller than that.'),
  ('cementing', 'advanced', 'module', 'm02-the-centralizer', 4, 'The lateral load on one centralizer is which product?', '["The air weight per metre times the spacing.", "The buoyed weight of the whole string below that point, resolved perpendicular to the hole using the local inclination.", "The buoyed weight per metre, the spacing, and the sine of the inclination.", "The buoyed weight per metre times half the spacing, since each centralizer carries half a span on each side of it."]'::jsonb, 2, 'Each centralizer carries half a span on either side, so one span in total.'),
  ('cementing', 'advanced', 'module', 'm02-the-centralizer', 5, 'The buoyed weight of this casing at 1440 kg/m3 is 345.6133299031847 N per metre. What is it made of?', '["The steel area times the density of the mud.", "The air weight of 43.16 kg per metre times gravity times one less 1440 over 7850.", "The nominal weight times gravity, reduced by the ratio of the mud density to the density of water rather than to steel.", "The steel cross-section times the difference between the steel density and the mud density, times gravity."]'::jsonb, 1, 'About eighteen percent of the air weight is carried by the fluid.'),
  ('cementing', 'advanced', 'module', 'm02-the-centralizer', 6, 'At zero inclination the lateral load is zero. What follows?', '["The standoff is exactly one, which is why both wells report 1 through their whole vertical section.", "The standoff is undefined and the row is skipped.", "The standoff is set by the mid-span sag alone, since the centralizer deflection is zero and the sag is not.", "The standoff is set by the clearance, which is the only term left once the load and the sag have both gone to zero."]'::jsonb, 0, 'Every standoff problem in drilling is a deviation problem.'),
  ('cementing', 'advanced', 'module', 'm02-the-centralizer', 7, 'Which term is deliberately left out of the lateral load, and named as such?', '["The buoyancy, which is applied separately.", "The friction and drag of running the string, since a casing being run is not in the static equilibrium the model assumes.", "The tension times the dogleg, which presses the string against the outside of a curve and can exceed the weight component.", "Tension times dogleg, which the engine''s header says is out of version one."]'::jsonb, 3, 'It matters most exactly where the standoff is already worst, which is in the build section.'),
  ('cementing', 'advanced', 'module', 'm02-the-centralizer', 8, 'A bow spring''s restoring force is quoted at 8900 N. At what?', '["At full compression against the wall.", "At the deflection the manufacturer measures in a standard test fixture, which is independent of the hole size it is run in.", "At a stated standoff, conventionally 67 percent, which is one point on a force-deflection curve.", "At zero deflection, so the number is the force the spring exerts when it is free and has not yet touched anything."]'::jsonb, 2, 'The engine turns that one point into a linear spring.'),
  ('cementing', 'advanced', 'module', 'm02-the-centralizer', 9, 'How does the engine compute the spring rate?', '["The restoring force divided by the clearance.", "The restoring force divided by one less the quoted standoff, times the clearance.", "The restoring force divided by the full clearance, which is the deflection at which the spring would be fully compressed.", "The restoring force times the quoted standoff, divided by the clearance, which gives the slope at the quoted point."]'::jsonb, 1, 'On this well''s open hole that is 8900 over 0.33 times 0.019049999999999997, which is 1415732.124393542 N per metre.'),
  ('cementing', 'advanced', 'module', 'm02-the-centralizer', 10, 'Why does the same centralizer have a different spring rate in a different hole size?', '["Because the deflection at which its force was quoted depends on the clearance, and the clearance depends on the hole.", "Because the steel behaves differently in a larger hole.", "Because the engine scales the restoring force by the ratio of the two clearances before computing the rate from it.", "Because a larger hole means a longer bow, and a longer bow is a softer spring for the same steel section."]'::jsonb, 0, 'In the cased section it is 1263294.5785784135 N per metre, softer than in the open hole.'),
  ('cementing', 'advanced', 'module', 'm02-the-centralizer', 11, 'What is wrong with the linear spring assumption?', '["Nothing, since bow springs are designed to be linear.", "It overstates the standoff, since a real spring takes a permanent set under load and never recovers its full restoring force.", "A real bow spring stiffens as it approaches full compression, so the model understates the standoff at large deflections.", "It assumes the force acts at the centralizer, when a real bow contacts the wall over a length and distributes the load."]'::jsonb, 2, 'Conservative, which is the right direction, and approximate.'),
  ('cementing', 'advanced', 'module', 'm02-the-centralizer', 12, 'At 12 m and 40 degrees on this well, the deflection is 0.0018830339076986488 m. What standoff is that?', '["0.098846924288643, the deflection over the clearance.", "0.901153075711357, which is the clearance less the deflection, over the clearance.", "0.742357202445576, which is the reported minimum standoff for the slant well at that spacing and inclination.", "0.8462214846722909, which is the value the horizontal well reaches at the same spacing and a higher inclination."]'::jsonb, 1, 'The reported minimum is lower, because the sag is subtracted from it.'),
  ('cementing', 'advanced', 'module', 'm02-the-centralizer', 13, 'Both wells'' centralizer deflections give standoffs above 0.84. What does that tell you?', '["That the centralizer is not what binds, and there would be nothing to design if it were.", "That both wells pass the API target comfortably.", "That the spring rate has been overestimated, since a real bow spring would deflect further than the linear model predicts.", "That the spacing could be widened without penalty, since the deflection is linear in the spacing and there is room."]'::jsonb, 0, 'The reported numbers are 0.742357202445576 and 0.599178961025609, and both are mid-span values.'),
  ('cementing', 'advanced', 'module', 'm02-the-centralizer', 14, 'A rigid blade of 0.206 m gives 0.7401574803149601 in the open hole. What is that number?', '["The blade diameter over the bore diameter.", "The blade less the casing, over twice the clearance, which is the same thing written with the clearance rather than the bore.", "The ratio of the two annular gaps, blade to casing and bore to casing, which is what standoff means for a fixed device.", "The blade less the casing outside diameter, over the bore less the casing outside diameter."]'::jsonb, 3, 'It is the BEST that device can do at the centralizer, before any sag.'),
  ('cementing', 'advanced', 'module', 'm02-the-centralizer', 15, 'The same 0.206 m blade gives 0.66046176113768 in the cased section. Why worse?', '["Because the cased section is more deviated.", "Because the excess is applied to the cased row as well, which enlarges its effective bore and reduces the blade''s ratio.", "Because the cased bore is larger, so the fixed blade takes up a smaller fraction of a larger clearance.", "Because the blade is oversized for the cased bore and is therefore clamped at the maximum standoff of one."]'::jsonb, 2, 'A bow spring in a bigger hole expands further and still pushes; a rigid centralizer just rattles.'),
  ('cementing', 'advanced', 'module', 'm03-the-span-between-them', 1, 'What is the pipe between two centralizers, mechanically?', '["A column in compression under the string weight.", "A beam supported at both ends, loaded by its own buoyed weight resolved perpendicular to the hole.", "A cantilever from the upper centralizer, since the lower one carries no load until the pipe has sagged onto it.", "A catenary, since the pipe is flexible enough over a twelve metre span to be treated as a cable rather than a beam."]'::jsonb, 1, 'It sags toward the low side, and the standoff at mid span is worse than at the ends.'),
  ('cementing', 'advanced', 'module', 'm03-the-span-between-them', 2, 'Write the sag formula.', '["The perpendicular weight per metre times the span to the fourth, over 384 times the bending stiffness.", "The perpendicular weight times the span squared over 8EI.", "Five times the perpendicular weight per metre times the span to the fourth, over 384 times the bending stiffness of the pipe.", "The perpendicular weight times the span cubed over 48 times the bending stiffness, which is the point-load deflection."]'::jsonb, 0, 'It is the fixed-end uniformly loaded beam result.'),
  ('cementing', 'advanced', 'module', 'm03-the-span-between-them', 3, 'The engine uses fixed ends rather than pinned. What difference does that make?', '["None, since the two coincide for a uniform load.", "A factor of two, which is the ratio between the fixed-end and simply-supported deflection coefficients for a uniform load.", "A factor of five, and fixed ends is the right choice because the casing continues through the centralizer rather than stopping.", "A factor of five: a pinned beam sags five times as much, with a coefficient of 5 over 384."]'::jsonb, 3, 'It is also the less conservative of the two by that factor.'),
  ('cementing', 'advanced', 'module', 'm03-the-span-between-them', 4, 'At 12 m and 90 degrees the sag is 0.004706160075469288 m. Against what?', '["A clearance of 0.021348699999999998 m, so about a fifth.", "The centralizer deflection of 0.0029294807169928587 m, which is the other term and is the larger of the two at that spacing.", "A clearance of 0.019049999999999997 m, so a quarter of the whole clearance from sag alone.", "The bending stiffness of 3965678.921984168 N m squared, which is what the sag is inversely proportional to."]'::jsonb, 2, 'At 40 degrees it is 0.0030250613857131267, which is sixteen percent.'),
  ('cementing', 'advanced', 'module', 'm03-the-span-between-them', 5, 'How does the engine combine the sag with the centralizer deflection?', '["It takes the larger of the two deflections.", "It adds the sag to the deflection the centralizer already gave away, then divides by the clearance.", "It adds them in quadrature, since the two act at different points along the span and are not simply cumulative there.", "It subtracts the sag from the standoff at the centralizer, expressed as a fraction, which is the same operation scaled."]'::jsonb, 1, 'The pipe is off centre by the centralizer''s deflection at the ends, and by that plus the sag in the middle.'),
  ('cementing', 'advanced', 'module', 'm03-the-span-between-them', 6, 'Why is the reported standoff always the mid-span value?', '["Because the mid-span value is the centralizer value less the sag, and the sag is never negative.", "Because the engine reports the mid-span value directly.", "Because the minimum function selects it whenever the inclination is above zero, and both wells build to a high angle.", "Because the centralizer value is not computed at all for a bow spring, only the mid-span deflection under the distributed load."]'::jsonb, 0, 'The minimum function in the code can never select the other branch.'),
  ('cementing', 'advanced', 'module', 'm03-the-span-between-them', 7, 'Doubling the spacing from 6 m to 12 m does what to the two terms?', '["Doubles both, since both are linear in the load.", "Doubles the deflection and quadruples the sag, since the sag depends on the square of the span rather than its fourth power.", "Doubles the centralizer deflection, which is linear in the spacing, and raises the sag by a factor of two to the fourth.", "Doubles the centralizer deflection and multiplies the sag by sixteen."]'::jsonb, 3, 'At 6 m the sag is a fifth of the deflection and at 12 m it is 1.6 times it.'),
  ('cementing', 'advanced', 'module', 'm03-the-span-between-them', 8, 'Where do the two terms cross on this casing?', '["At about 20 m, where the standoff reaches zero.", "They never cross, since the sag is always the larger of the two at any spacing a centralizer programme would actually use.", "At about 9 m of spacing, after which the sag runs away.", "At about 6 m, below which the centralizer deflection dominates and above which the sag does, on this casing and clearance."]'::jsonb, 2, 'Knowing which side of the crossover you are on decides which lever to pull.'),
  ('cementing', 'advanced', 'module', 'm03-the-span-between-them', 9, 'Which buys more on the horizontal well, halving the spacing or doubling the spring?', '["Doubling the spring, since it acts at the centralizer.", "Halving the spacing: 12 m to 9 m buys 21 points and 8900 to 17800 N buys 8.", "They are comparable, since both terms respond to the load and the load is what both levers reduce in the same proportion.", "Doubling the spring on a slant well and halving the spacing on a horizontal one, because the sag term scales with the sine."]'::jsonb, 1, 'The spring does nothing at all to the sag.'),
  ('cementing', 'advanced', 'module', 'm03-the-span-between-them', 10, 'Why does the design conversation naturally become one about centralizers?', '["Because a centralizer is a thing you can hold and buy, and a span is an absence.", "Because the spacing is fixed by the joint length.", "Because the centralizer deflection is the larger of the two terms at the spacings a real programme uses on a deviated well.", "Because the sag term was only added to the standard calculation recently, and older programmes did not carry it at all."]'::jsonb, 0, 'The arithmetic says it should be a conversation about how many.'),
  ('cementing', 'advanced', 'module', 'm03-the-span-between-them', 11, 'Both wells'' standoff reaches exactly zero at some spacing. Where does zero come from?', '["The bow spring being fully compressed against the wall.", "The clamp in the code, which limits the deflection to the clearance and therefore the standoff to zero at large spacings.", "The sag reaching the clearance, which on this casing happens at 17.021127200569346 m at ninety degrees.", "The sag reaching the whole clearance, not the centralizer bottoming out."]'::jsonb, 3, 'The centralizer would need a spacing of 78.03430781229383 m at 90 degrees to bottom out.'),
  ('cementing', 'advanced', 'module', 'm03-the-span-between-them', 12, 'The slant well hits zero at 20 m and the horizontal at 18. What is the ratio of the exact answers?', '["The ratio of the two sines, 1.5557238268604126.", "The square root of the ratio of the two sines, since the sag is quadratic in the span and linear in the perpendicular load.", "The fourth root of the ratio of the two sines, because the sag goes as the fourth power of the span.", "The ratio of the two clearances, since both wells have the same casing and the same centralizer but different hole sizes."]'::jsonb, 2, '19.009532790549464 over 17.021127200569346 is 1.1168, which is that fourth root.'),
  ('cementing', 'advanced', 'module', 'm03-the-span-between-them', 13, 'Between 12 m and 16 m the horizontal well goes from 0.599178961025609 to 0.014185608531566366. What is the lesson?', '["That 16 m spacing is the industry standard limit.", "Four metres of spacing takes the job from nearly acceptable to certainly channelled.", "That the relationship is linear over that range, so a simple interpolation between the two is adequate for design purposes.", "That the centralizer has bottomed out by 16 m, and no stronger spring could recover the standoff at that spacing."]'::jsonb, 1, 'Twenty metres is one centralizer every one and a half joints, and it is a hard floor.'),
  ('cementing', 'advanced', 'module', 'm03-the-span-between-them', 14, 'Heavier mud improves the standoff. Why?', '["Because the lateral load is the BUOYED weight, and buoyancy rises with the density of the fluid.", "Because a denser fluid supports the pipe hydrodynamically.", "Because a heavier mud has a higher yield stress, which resists the pipe settling toward the low side of the hole.", "Because the buoyancy factor multiplies the clearance rather than the weight, so a heavier mud widens the effective annulus."]'::jsonb, 0, 'At 1030 the casing weighs 367.71964273630573 N per metre and at 2000 it weighs 315.4193416433121.'),
  ('cementing', 'advanced', 'module', 'm03-the-span-between-them', 15, 'How big is the mud density effect compared with the spacing effect?', '["Comparable, which is why heavy mud is used for standoff.", "Larger, since the buoyancy affects both the centralizer deflection and the sag while the spacing affects only the sag term.", "Small: the whole realistic density range buys about six points on the horizontal well against twenty one for 12 m to 9.", "Negligible, since the buoyancy factor changes by less than one percent over the range of mud weights actually used."]'::jsonb, 2, 'Nobody chooses a mud weight to improve standoff; it is a side effect worth knowing the sign of.'),
  ('cementing', 'advanced', 'module', 'm04-choosing-a-spacing', 1, 'What question does the required spacing routine answer?', '["The spacing that gives exactly the target standoff.", "The WIDEST spacing at which the minimum standoff anywhere on the string still reaches the target.", "The tightest spacing that is achievable given the running drag the centralizers impose on the string as it goes in the hole.", "The spacing at which the mid-span sag equals the deflection at the centralizer, which is the crossover of the two terms."]'::jsonb, 1, 'Wider is cheaper, so the answer is the design.'),
  ('cementing', 'advanced', 'module', 'm04-choosing-a-spacing', 2, 'What are the two guards on the bisection?', '["Return the widest spacing if even that meets the target, and return null if the tightest does not.", "Return zero and return the tightest spacing.", "Refuse a target above one and refuse a target below zero, since a standoff outside that range has no physical meaning.", "Return the widest if the target is met there, and the tightest if it is not, so an answer is always produced."]'::jsonb, 0, 'Null means not achievable, and it is a different answer from the tightest spacing.'),
  ('cementing', 'advanced', 'module', 'm04-choosing-a-spacing', 3, 'Why return null rather than the tightest spacing when the target cannot be reached?', '["Because a null is easier to test for downstream.", "Because the tightest spacing in the search range is arbitrary, and returning it would imply the range had physical meaning.", "Because returning three metres would hide the second case inside the first, and the reader would run it and still fail.", "Because they are different answers: one is a design and the other is a different conversation."]'::jsonb, 3, 'The second conversation is about a different centralizer, a different hole size, or accepting a lower standoff.'),
  ('cementing', 'advanced', 'module', 'm04-choosing-a-spacing', 4, 'What does the bisection assume about the function it searches?', '["That the function is continuous but not monotone.", "That the standoff is linear in the spacing, so the bisection converges in a fixed number of steps regardless of the range.", "That the minimum standoff falls monotonically as the spacing rises, which both terms do.", "That the target is achievable somewhere in the range, which is why the two guards are checked before the search begins."]'::jsonb, 2, 'The deflection is linear in the spacing and the sag is quartic, and both reduce the standoff.'),
  ('cementing', 'advanced', 'module', 'm04-choosing-a-spacing', 5, 'The two wells require 13.05523892558449 m and 11.187558579905271 m. Both are run at 12. What follows?', '["Both pass, since 12 is between the two answers.", "The same programme passes on one well and fails on the other.", "Both fail, since a required spacing is the tightest achievable and running wider than it means missing the target on both.", "Neither can be assessed, since a required spacing is computed against the worst interval and both wells have several."]'::jsonb, 1, 'Twelve is inside 13.06 and outside 11.19.'),
  ('cementing', 'advanced', 'module', 'm04-choosing-a-spacing', 6, 'The two wells'' loads differ by a factor of 1.5557238268604126 and their spacings by 1.1669426204421298. Why less?', '["Because the sag goes as the fourth power, so the spacing scales as the fourth root of the inverse load.", "Because the centralizer deflection is unchanged.", "Because the required spacing is bisected against the API target rather than against the load, so the two are not proportional.", "Because the clearance is the same on both wells, and the clearance appears in the denominator of both standoff terms."]'::jsonb, 0, 'A well that is 56 percent harder needs its centralizers only 17 percent closer.'),
  ('cementing', 'advanced', 'module', 'm04-choosing-a-spacing', 7, 'One number comes back for the whole string. What would a real programme specify instead?', '["A null when the target cannot be reached.", "The minimum standoff at the answer, which the caller has to compute separately by running the profile at that spacing.", "One number per string, computed against the worst interval, when a real programme would be wide in the vertical and tight below.", "A spacing profile, staged by interval, which is what a real programme would specify."]'::jsonb, 3, 'Both wells report a standoff of exactly 1 through their vertical sections, where a centralizer is doing nothing.'),
  ('cementing', 'advanced', 'module', 'm04-choosing-a-spacing', 8, 'The volume side uses one bore and the standoff side another. Which is which?', '["The volume side uses the nominal bore.", "Both use the washed-out bore, since the excess is applied when the annulus rows are built and both calculations read them.", "The volume side uses the washed-out bore and the standoff side the nominal one.", "The volume side uses the effective bore and the standoff side the drift diameter of the previous casing string above it."]'::jsonb, 2, 'The standoff call passes an excess of zero, explicitly, in the function body.'),
  ('cementing', 'advanced', 'module', 'm04-choosing-a-spacing', 9, 'What is the argument FOR the standoff side using the nominal bore?', '["That the excess is only a volume convention.", "A centralizer is sized to the bit, and its restoring force is quoted in a nominal hole size.", "That the washed-out bore is not known at the time the centralizer programme is written, which is before the hole is drilled.", "That a washed-out section is usually short, so using the nominal bore over the whole string is a reasonable average."]'::jsonb, 1, 'Computing the spring rate against a washed-out clearance would apply the manufacturer''s number outside its own geometry.'),
  ('cementing', 'advanced', 'module', 'm04-choosing-a-spacing', 10, 'Which way does the nominal-bore choice make the error go?', '["Optimistic, because a washed-out hole gives the pipe more room to move off centre.", "Conservative, because a bigger hole means more clearance.", "Neither, since the sag becomes a smaller fraction of a larger clearance and the two effects cancel almost exactly.", "It depends on the centralizer type, being optimistic for bow springs and conservative for rigid blades."]'::jsonb, 0, 'It is much worse for a rigid centralizer, whose standoff is a pure ratio of diameters.'),
  ('cementing', 'advanced', 'module', 'm04-choosing-a-spacing', 11, 'What happens to a 0.206 m rigid blade when the hole washes out to 0.22104932820526735 m?', '["Nothing, since the blade ratio is a fixed property.", "It rises, since a larger bore means a larger clearance and the same blade takes up a proportionally greater share of it.", "It falls by about nine points, straight off, with no spring to take up the slack the washout has created for it.", "Its standoff at the centralizer falls from 0.7401574803149601 to 0.6520332493064135."]'::jsonb, 3, 'A bow spring in the same washed-out hole loses much less.'),
  ('cementing', 'advanced', 'module', 'm04-choosing-a-spacing', 12, 'Which omission from the standoff calculation does the engine name in its own header?', '["The cuttings bed on the low side of the hole.", "Casing rotation and reciprocation, which is the most effective mud removal technique and is stated as being out of scope.", "The tension times dogleg lateral-load term, which it says is deliberately out of version one.", "The residual curvature of the pipe itself, which the beam model assumes away by treating the span as initially straight."]'::jsonb, 2, 'It matters most exactly where the standoff is already worst, which is in the build section.'),
  ('cementing', 'advanced', 'module', 'm04-choosing-a-spacing', 13, 'Which direction do the five standoff omissions push the answer?', '["All optimistic, so the reported number is an upper bound.", "Not all the same way, which is the least comfortable kind of approximation.", "All conservative, so a job that passes on the reported number will pass on the real one with margin to spare as well.", "All negligible on a well of this geometry, which is why the standard calculation has survived unchanged for so long."]'::jsonb, 1, 'Tension times dogleg makes it worse, cuttings beds make it better, and residual curvature could go either way.'),
  ('cementing', 'advanced', 'module', 'm04-choosing-a-spacing', 14, 'Tripling the restoring force on the horizontal well buys 10.3 points. What does 12 m to 10 m buy?', '["15.4 points, and going to 9 m buys 20.7, because the spacing acts on both terms.", "About 5 points, since the sag is unchanged.", "About 30 points, since the sag goes as the fourth power and a sixth off the spacing is a large fraction off the sag.", "The same 10.3 points, since the two levers are equivalent once the load is expressed per unit of restoring force."]'::jsonb, 0, 'The force lever only touches the centralizer deflection, which is not what binds.'),
  ('cementing', 'advanced', 'module', 'm04-choosing-a-spacing', 15, 'What is the sag-only ceiling, and what is it for?', '["The standoff at zero spacing, which is one.", "The standoff a rigid centralizer with a blade equal to the bore would reach, which is the theoretical maximum for the geometry.", "One less the sag over the clearance, which caps what any spring can achieve and should be computed before choosing a device.", "One less the sag over the clearance: the best any centralizer can do at that spacing, and it is 0.7529574763533182 at 12 m."]'::jsonb, 3, 'If it is below your target, no centralizer will do and the spacing has to come down.'),
  ('cementing', 'advanced', 'module', 'm05-the-checklist-and-its-edges', 1, 'What are the five items on the placement checklist?', '["Volumes, placement, standoff, chemistry and time.", "Density hierarchy, standoff, no free fall, floats hold, and annular velocity.", "Density hierarchy, standoff, achieved top of cement, peak circulating density and the annular velocity at the slowest row.", "Free fall, the float differential, the top of cement, the fracture margin and the mud removal efficiency percentage."]'::jsonb, 1, 'Each carries a detail string with its own numbers in it.'),
  ('cementing', 'advanced', 'module', 'm05-the-checklist-and-its-edges', 2, 'What does the checklist return?', '["A list of items with an identifier, a boolean and a detail string, plus a count passed and a total.", "A single percentage between zero and a hundred.", "A weighted score out of a hundred, with the weights chosen so that standoff carries the largest share of the total.", "A pass or fail verdict for the job as a whole, derived from whether every one of the five individual items holds."]'::jsonb, 0, 'Five and five on the slant well, four and five on the horizontal one.'),
  ('cementing', 'advanced', 'module', 'm05-the-checklist-and-its-edges', 3, 'Which checklist item is conditional on extra inputs?', '["The standoff, which needs a centralizer definition.", "The free-fall item, which needs a pump rate and is therefore skipped on a run made purely to compute the annular volumes.", "The annular velocity one, so the total can be four rather than five and a caller comparing against a hard-coded five is wrong.", "The annular velocity, which is only added if the annulus rows and a pump rate were both supplied."]'::jsonb, 3, 'The engine''s own test asserts the total is at least five rather than exactly five.'),
  ('cementing', 'advanced', 'module', 'm05-the-checklist-and-its-edges', 4, 'The horizontal well fails one item. Which?', '["Annular velocity, at the slowest annulus row.", "No free fall, since the two-slurry programme on that well does free fall at one of the sixty one steps in the placement.", "Standoff, at 0.599178961025609 against the 67 percent target.", "Float holds, since its float differential of 570815.1577260531 Pa is only a tenth of the slant well''s and is marginal."]'::jsonb, 2, 'Same job, same fluids, same rate, same centralizer, and the trajectory fails one item.'),
  ('cementing', 'advanced', 'module', 'm05-the-checklist-and-its-edges', 5, 'What is NOT on the checklist?', '["The annular velocity, which is a hydraulics matter.", "The achieved top of cement, the peak circulating density and the volume reconciliation.", "The density hierarchy, which the placement simulation warns about separately and which is therefore not repeated here.", "The standoff, since it comes from a different function and the checklist only reads results from the placement itself."]'::jsonb, 1, 'Those are computed and reported elsewhere; the checklist is a placement quality list rather than a job summary.'),
  ('cementing', 'advanced', 'module', 'm05-the-checklist-and-its-edges', 6, 'The annular velocity is the pump rate over what?', '["The capacity of each annulus row, with the MINIMUM of the results reported.", "The total annular volume, over the job time.", "The average annular capacity, weighted by the length of each row so that a short narrow section does not dominate.", "The effective bore area less the casing cross-section, which is the same thing computed from the diameters instead."]'::jsonb, 0, 'On this well that is 1.4973771889585683 cased and 1.476222714457212 in the washed-out open hole.'),
  ('cementing', 'advanced', 'module', 'm05-the-checklist-and-its-edges', 7, 'Which of the two annuli on this well is slower, and why?', '["The cased section, because it is the narrower annulus.", "The open hole, because the 8-1/2 inch bit drilled a smaller hole than the 9-5/8 inch casing above it was run through.", "The open hole, because the excess inflated its capacity and a wider annulus is a slower one at the same pump rate.", "The open hole, because the 15 percent excess made it the wider of the two."]'::jsonb, 3, 'At the bit size the open hole would have been the faster of the two, at 1.6976561216257935 m/s.'),
  ('cementing', 'advanced', 'module', 'm05-the-checklist-and-its-edges', 8, 'The annular velocity target in the checklist is what, and where from?', '["One metre per second, from API Recommended Practice.", "Three tenths of a metre per second, taken from the turbulent displacement criterion for a Herschel-Bulkley slurry in an annulus.", "Three tenths of a metre per second, hard coded, and it is a screening floor rather than a design criterion.", "Whatever velocity gives a Reynolds number above 3000 in the narrowest annulus, computed from the slurry rheology."]'::jsonb, 2, 'The literature offers several criteria and some of them want the opposite.'),
  ('cementing', 'advanced', 'module', 'm05-the-checklist-and-its-edges', 9, 'Is the annular velocity item binding on this job?', '["Yes, it is what set the design rate of 0.02.", "No. Both velocities are about five times the target and neither constrained the rate choice.", "Yes on the horizontal well and no on the slant one, since the horizontal annulus is longer and therefore slower at the same rate.", "It cannot be determined, since the target is a screening value and there is no defensible criterion to compare it against."]'::jsonb, 1, 'It stops being slack on a large-diameter surface casing in a washed-out hole.'),
  ('cementing', 'advanced', 'module', 'm05-the-checklist-and-its-edges', 10, 'Annular velocity is the third pull on the pump rate. Which way?', '["The same way as free fall: faster is better, so two constraints want it high and one wants it low.", "The same way as the fracture limit: slower is better.", "It pulls both ways, since a higher velocity improves mud removal and a lower one reduces the risk of eroding the open hole.", "It does not pull at all, since the velocity is a consequence of the rate rather than a constraint on choosing it."]'::jsonb, 0, 'On this job the velocity constraint is slack and the other two decide.'),
  ('cementing', 'advanced', 'module', 'm05-the-checklist-and-its-edges', 11, 'Why does the engine not report a mud removal efficiency percentage?', '["Because the calculation is too expensive to run.", "Because the API specification forbids reporting a single figure of merit for a cement job without a bond log to support it.", "Because the weights are unmeasured, a score hides which item failed, and no field measurement ever returns a percentage.", "Because the weights would be invented, it would hide which item failed, and it cannot be falsified."]'::jsonb, 3, 'The engine''s own comment says honest, not a fake efficiency percentage.'),
  ('cementing', 'advanced', 'module', 'm05-the-checklist-and-its-edges', 12, 'What is the real damage a percentage does?', '["It is harder to compute than a list of booleans.", "It cannot be compared between jobs, since the weighting depends on the geometry and no two jobs weight the items the same.", "It sounds like a measurement, and carries that implication into reports and decisions.", "It encourages designers to optimise the score rather than the job, which is a different objective from isolating the reservoir."]'::jsonb, 2, 'A list of five booleans carries no such implication.'),
  ('cementing', 'advanced', 'module', 'm05-the-checklist-and-its-edges', 13, 'What does the list claim that a score does not?', '["A quantitative estimate of the isolation achieved.", "Five specific things, each true or false of this job, each with the number that decided it.", "That the job will isolate the reservoir, provided all five items hold and the slurry sets as the laboratory predicted it would.", "A ranking against other jobs in the same field, which is what a percentage is really used for in practice."]'::jsonb, 1, 'The claim is smaller, and it is true.'),
  ('cementing', 'advanced', 'module', 'm05-the-checklist-and-its-edges', 14, 'Where does the same discipline appear elsewhere in this suite?', '["Casing and Tubing reports a status per section per case rather than one verdict for the string.", "Hydraulics reports a single ECD for the whole well.", "Geomechanics reports a quality score, which is the exception that proves the rule about single figures of merit.", "Well Control reports a kill sheet with a pass or fail on it, derived from the same kind of weighted checklist as this one."]'::jsonb, 0, 'Collapsing fourteen verdicts to one word loses the only useful information.'),
  ('cementing', 'advanced', 'module', 'm05-the-checklist-and-its-edges', 15, 'How many things does this tier teach and certify nowhere?', '["Five, matching the five checklist items.", "Two, casing movement and intermixing, which are the only two of the omissions that would change any reported number.", "Nine, from casing rotation through to cement bond evaluation, and the go-live asserts it.", "None, since everything taught in the tier is graded by at least one of the six capstone fields at this level."]'::jsonb, 2, 'For each of them either the engine cannot produce the answer, or it produces a screening version.'),
  ('cementing', 'advanced', 'module', 'm06-the-expert-reading', 1, 'Summarising the Expert tier: what decides the standoff?', '["The restoring force of the centralizer chosen.", "The span between the centralizers, far more than the centralizers themselves.", "The clearance, since both terms are expressed as fractions of it and a tighter hole therefore gives a better standoff.", "The mud density, through the buoyancy factor, which is the only input that appears in both of the two standoff terms."]'::jsonb, 1, 'The device is what you buy and the span is what binds.'),
  ('cementing', 'advanced', 'module', 'm06-the-expert-reading', 2, 'Which two terms make up the standoff, and how do they scale with the spacing?', '["The centralizer deflection, linear, and the mid-span sag, quartic.", "Both scale linearly with the spacing.", "The deflection scales quartically, since it depends on the load which depends on the span to the fourth power through the sag.", "The deflection is quartic and the sag is linear, which is why widening the spacing hurts the centralizer more than the span."]'::jsonb, 0, 'At 6 m the sag is a fifth of the deflection and at 12 m it is 1.6 times it.'),
  ('cementing', 'advanced', 'module', 'm06-the-expert-reading', 3, 'A capstone changes the casing size, the mud and the centralizer. What stays the same?', '["The clearance, since the casing size is unchanged.", "The bending stiffness, since it is a property of the steel rather than of the section and does not change with the pipe size.", "The buoyed weight, since the mud change and the casing change happen to cancel in the buoyancy factor calculation.", "The method: a lateral load, a spring rate, a deflection, a sag, and the smaller of the two."]'::jsonb, 3, 'Nothing about the procedure depends on the numbers it is given.'),
  ('cementing', 'advanced', 'module', 'm06-the-expert-reading', 4, 'A capstone runs a 30 percent excess in its volume sheet. What does that do to its standoff?', '["It increases the clearance by thirty percent.", "It increases the clearance by about fourteen percent, since the excess applies to the area and the clearance goes as its root.", "Nothing at all, because the standoff calculation runs the annulus rows at zero excess.", "It reduces the standoff, since a washed-out hole gives the pipe more room to move away from the centre of the annulus."]'::jsonb, 2, 'A clearance of 0.042 rather than 0.033 means the wrong bore was used.'),
  ('cementing', 'advanced', 'module', 'm06-the-expert-reading', 5, 'A capstone spring rate comes out around a million newtons per metre. Is that plausible?', '["No, since a bow spring is a much softer device than that.", "Yes, because the clearance is in the denominator and a clearance of a few centimetres makes the rate large.", "No, since the restoring force is of the order of ten thousand newtons and the deflection is of the order of a millimetre.", "Only in a cased section, since the larger clearance there raises the rate while the open hole gives a smaller one."]'::jsonb, 1, 'The rate times 0.33 times the clearance must give back the restoring force exactly.'),
  ('cementing', 'advanced', 'module', 'm06-the-expert-reading', 6, 'Which free check catches a capstone standoff read from the wrong interval?', '["The reported minimum must be at or below the standoff at the centralizer of the same interval.", "The minimum must be above the API target.", "The minimum must equal the standoff at the centralizer less the sag divided by the clearance, which is a closed form.", "The required spacing must be larger than the spacing being run, which follows only if the job passes the target at all."]'::jsonb, 0, 'The sag is never negative, so the mid-span value is always the smaller of the two.'),
  ('cementing', 'advanced', 'module', 'm06-the-expert-reading', 7, 'Which free check catches a capstone required spacing that disagrees with the profile?', '["The required spacing must be below thirty metres.", "The required spacing must equal the spacing at which the sag reaches the clearance, which is the point of zero standoff.", "If the profile passes at the spacing being run, the bisected required spacing has to come back larger than that spacing.", "If the job passes the target at the spacing run, the required spacing must exceed that spacing."]'::jsonb, 3, 'A bisection returning something below the spacing run means the profile and the verdict disagree.'),
  ('cementing', 'advanced', 'module', 'm06-the-expert-reading', 8, 'A capstone grades a rigid centralizer alongside a bow spring. What is the expected relationship?', '["The rigid one is always better, being stiffer.", "They agree at the centralizer and differ only at mid span, since the sag is computed identically for both device types.", "The rigid one is capped by its blade ratio and the bow spring is not, so it can be worse despite the same spacing.", "The rigid one is better in a cased section and worse in open hole, since its blade is sized to the previous casing bore."]'::jsonb, 2, 'A bow spring under light load reaches one; a rigid centralizer never does.'),
  ('cementing', 'advanced', 'module', 'm06-the-expert-reading', 9, 'A capstone mud density of 1300 rather than 1440 does what to the standoff?', '["Makes it slightly better, since a lighter mud is thinner.", "Makes it slightly worse, because less buoyancy means a heavier casing and a larger lateral load.", "Nothing, since the buoyancy factor cancels between the lateral load and the spring rate in the standoff expression.", "Makes it much worse, since the buoyancy factor changes by ten percent and the sag is quartic in the resulting load."]'::jsonb, 1, 'The whole realistic density range is worth about six points on a horizontal well.'),
  ('cementing', 'advanced', 'module', 'm06-the-expert-reading', 10, 'What does an Expert in this course sign their name to?', '["A standoff profile, a required spacing and a five-item checklist, with the numbers that produced each.", "A guarantee that the cement job will isolate the well.", "A complete cement programme, including the volumes, the placement pressures, the rate window and the centralizer spacing.", "A prediction of the displacement efficiency achieved, expressed as a percentage of the annulus swept clean by the cement."]'::jsonb, 0, 'Whether the mud actually left is one of four things this course does not compute.'),
  ('cementing', 'advanced', 'module', 'm06-the-expert-reading', 11, 'Which four things decide whether a cement job worked, and which does this course compute?', '["Volumes, placement, standoff and chemistry, and it does three.", "Whether the volumes were right, the placement was right, the standoff was adequate and the slurry set, and it does the first three.", "Setting, bonding, mud removal and isolation, and this course computes none of the four directly.", "Whether the cement set, bonded, displaced the mud and isolated the well, and it computes none of them."]'::jsonb, 3, 'It makes the decisions that CAN be made before the job, on stated assumptions.'),
  ('cementing', 'advanced', 'module', 'm06-the-expert-reading', 12, 'Which course''s cementing collapse case is exactly the column this course places?', '["Well Integrity and P and A, decades later.", "Drilling Fluids and Hydraulics, which supplies the loss kernel and the rheology fits the placement simulation imports.", "Casing and Tubing Design, which meets this course at the same annulus from the other side.", "Geomechanics, which supplies the fracture gradient the peak circulating density at the previous shoe is compared against."]'::jsonb, 2, 'Water inside the pipe and wet cement outside, which is the third of its seven load cases.'),
  ('cementing', 'advanced', 'module', 'm06-the-expert-reading', 13, 'What are the three habits the course closes on?', '["Order generously, pump slowly and centralize tightly.", "Write the excess next to the volume, bisect the edge, and compute the sag before choosing the centralizer.", "Check the volumes twice, run the placement at three rates, and compute the standoff at both the nominal and washed-out bore.", "Report the version string, log every assumption, and never quote a number without the tolerance that goes with it."]'::jsonb, 1, 'All three are the same habit: find out which number the answer depends on.'),
  ('cementing', 'advanced', 'module', 'm06-the-expert-reading', 14, 'Which two quantities in this tier surprisingly do not depend on the length of the string?', '["Neither the buckling of a centralizer span nor the standoff depends on the string length: both are local.", "The required spacing and the minimum standoff.", "The lateral load and the sag, since both are computed per span and the number of spans does not enter either expression.", "The spring rate and the blade ratio, since both are properties of the device rather than of the string it is fitted to."]'::jsonb, 0, 'Everything in the standoff calculation is a property of one span.'),
  ('cementing', 'advanced', 'module', 'm06-the-expert-reading', 15, 'Where does a mud channel from this job finally become visible?', '["At the pressure test after the cement sets.", "At the next casing shoe leak-off test, which is the first time the cement sheath is loaded along part of its length.", "Twenty years on, in the Well Integrity and P and A course, when somebody asks whether the barrier is still a barrier.", "In Well Integrity and P and A, decades later, as sustained casing pressure or a failed abandonment."]'::jsonb, 3, 'By then the well is producing and the remedy is a remedial squeeze.'),
  ('cementing', 'advanced', 'final', null, 1, 'A pipe is pushed against one side of the hole. What happens to the cement?', '["It fills both sides equally, being incompressible.", "It takes the wide side, because resistance in a slot goes roughly as the inverse cube of the gap.", "It takes the narrow side first, since the capillary pressure there is higher and draws the slurry in ahead of the wide side.", "It fills from the bottom up, so the last of the mud is pushed ahead of it and out of the annulus at surface."]'::jsonb, 1, 'The mud on the narrow side stays where it is, as a channel.'),
  ('cementing', 'advanced', 'final', null, 2, 'A well develops sustained casing pressure after six years. Which cement failure fits?', '["Gas migrating up a mud channel left on the narrow side of an eccentric annulus.", "An under-displaced job, which set inside the casing.", "A cement top short of its target, which would have left the interval above the shoe uncemented and open to the annulus.", "A failed pressure test at the shoe, which would have been detected before the next hole section was drilled ahead."]'::jsonb, 0, 'It is the failure the standoff calculation exists to prevent.'),
  ('cementing', 'advanced', 'final', null, 3, 'Standoff of 0.6 is an eccentricity of what?', '["0.6, since the two are the same quantity.", "1.67, since eccentricity is the reciprocal of the standoff and runs from one at centre to infinity at the wall.", "0.4, and confusing the two is a real error because a standoff of 67 percent is an eccentricity of 33.", "0.4, because eccentricity is one less the standoff."]'::jsonb, 3, 'They carry the same information and run in opposite directions.'),
  ('cementing', 'advanced', 'final', null, 4, 'This well''s open hole clearance is 0.019049999999999997 m. Where does that come from?', '["The full difference between the two diameters.", "Half the difference between the effective bore of 0.22104932820526735 m and the casing, once the excess has been applied.", "Half the difference between the 0.2159 m bit and the 0.1778 m casing outside diameter.", "Half the difference between the previous casing bore of 0.2204974 m and the casing outside diameter of 0.1778 m."]'::jsonb, 2, 'Nineteen millimetres is the whole distance the pipe has to move to be touching.'),
  ('cementing', 'advanced', 'final', null, 5, 'The API 67 percent number appears twice in this engine. Where?', '["As the target and as the default rigid blade ratio.", "As the checklist target, and as the standoff at which a bow spring''s restoring force is quoted.", "As the target and as the fraction of the clearance the mid-span sag is allowed to take up before the standoff is reported as zero.", "As the target and as the default excess factor, both being conventions from the same API specification."]'::jsonb, 1, 'The two uses are unrelated and the engine exposes the second separately so they can be decoupled.'),
  ('cementing', 'advanced', 'final', null, 6, 'A bow spring and a rigid centralizer are put in the same washed-out hole. Which loses more?', '["The rigid one, because its standoff is a ratio of diameters and it has no spring to take up the slack.", "The bow spring, since it was quoted at a nominal size.", "Neither, since the standoff calculation runs at zero excess and does not know the hole washed out in the first place.", "They lose equally, since both are computed against the same clearance and the same lateral load in the same interval."]'::jsonb, 0, 'A bow spring in a bigger hole expands further and still pushes.'),
  ('cementing', 'advanced', 'final', null, 7, 'One bow spring carries how much sideways force, and from what?', '["The air weight per metre times the spacing.", "The buoyed weight of the whole string above that point, resolved perpendicular to the hole through the local inclination.", "The buoyed weight per metre times the spacing times the sine of the hole angle, being the span each centralizer carries.", "The buoyed weight per metre, the spacing, and the sine of the inclination."]'::jsonb, 3, 'Each carries half a span on either side, so one span in total.'),
  ('cementing', 'advanced', 'final', null, 8, 'This casing weighs 43.16 kg per metre in air. What does it weigh in 1440 kg/m3 mud?', '["43.16 N per metre, since the units are the same.", "423.25501399999996 N per metre, which is the air weight times gravity before the buoyancy factor has been applied to it.", "345.6133299031847 N per metre, which is about eighteen percent less than its air weight.", "About 315 N per metre, which is what the same string weighs in a 2000 kg/m3 mud rather than in the 1440 one."]'::jsonb, 2, 'The buoyancy factor is one less 1440 over 7850.'),
  ('cementing', 'advanced', 'final', null, 9, 'At zero inclination the standoff is exactly one. Why?', '["The clearance is largest in the vertical section.", "The sine of the inclination is zero, so the lateral load and the sag are both zero.", "The bow spring is undeflected because the string is in tension there, and tension holds the pipe centred in a vertical hole.", "The engine skips vertical rows, and reports one as a placeholder rather than computing a standoff at all."]'::jsonb, 1, 'Every standoff problem in drilling is a deviation problem.'),
  ('cementing', 'advanced', 'final', null, 10, 'Which term does the engine''s own header say is out of version one?', '["The tension times dogleg lateral-load term.", "Casing rotation and reciprocation.", "The residual curvature of the pipe itself, which the beam model assumes away by treating each span as initially straight.", "The cuttings bed on the low side of the hole, which the hole cleaning module of the hydraulics course computes separately."]'::jsonb, 0, 'It matters most exactly where the standoff is already worst, in the build section.'),
  ('cementing', 'advanced', 'final', null, 11, 'How does the engine convert a quoted restoring force into a spring rate?', '["By dividing it by the full clearance.", "By dividing it by the deflection at the API target, taken as a fixed two thirds of a millimetre regardless of the hole size.", "By dividing the force by the deflection at the quoted standoff, which puts the clearance inside the spring rate itself.", "By dividing it by the deflection at which it was quoted, which is one less the quoted standoff times the clearance."]'::jsonb, 3, 'So the same device has different rates in different hole sizes.'),
  ('cementing', 'advanced', 'final', null, 12, 'The spring rate in this well''s open hole is 1415732.124393542 N per metre and in the cased section 1263294.5785784135. Why?', '["The cased section uses a different centralizer.", "The cased section is less deviated, so the lower lateral load there implies a softer spring for the same restoring force.", "The cased clearance is larger, and the clearance is in the denominator of the rate.", "The excess is applied to the open hole row, which reduces its clearance and therefore raises the spring rate there."]'::jsonb, 2, 'A softer spring in the bigger hole, from the same device, and that follows from the convention rather than the steel.'),
  ('cementing', 'advanced', 'final', null, 13, 'What is wrong with the linear spring model, and in which direction?', '["It overstates the standoff, so it is not conservative.", "A real spring stiffens near full compression, so the model understates the standoff at large deflections.", "It assumes the force acts at a point, when a real bow contacts the wall over a length and spreads the load along the span.", "It ignores the permanent set a bow takes under load, which means the real standoff falls over the time the string is run."]'::jsonb, 1, 'Conservative, which is the right direction, and approximate.'),
  ('cementing', 'advanced', 'final', null, 14, 'A 0.206 m rigid blade in a 0.2159 m hole around 0.1778 m casing gives what?', '["0.7401574803149601, which is the best that device can do before any sag.", "0.954, the ratio of the two diameters.", "0.6520332493064135, which is the same blade in the washed-out hole once the fifteen percent excess has been applied.", "0.66046176113768, which is the same blade in the cased section where the bore is 0.2204974 m rather than 0.2159."]'::jsonb, 0, 'A bow spring under light load reaches one and a rigid centralizer never does.'),
  ('cementing', 'advanced', 'final', null, 15, 'The mid-span sag formula divides by 384 EI. What beam is that?', '["A simply supported beam under a point load.", "A cantilever fixed at one end, which is the conservative treatment for a span whose lower support has not yet been reached.", "A fixed-end beam under a uniform load, which is right because the casing continues through the centralizer rather than stopping.", "A fixed-end uniformly loaded beam, which sags a fifth as much as a pinned-end one."]'::jsonb, 3, 'The pinned coefficient is 5 over 384.'),
  ('cementing', 'advanced', 'final', null, 16, 'The sag at 12 m and 90 degrees on this casing is 0.004706160075469288 m. As a fraction of the clearance?', '["About 5 percent, which is why it rarely matters.", "About 16 percent, which is the figure at 40 degrees rather than at the 90 degrees a horizontal well reaches in its lateral.", "About 25 percent, on a clearance of 0.019049999999999997 m.", "About 50 percent, which is why the horizontal well fails the API target at that spacing while the slant one passes."]'::jsonb, 2, 'At 40 degrees it is 16 percent.'),
  ('cementing', 'advanced', 'final', null, 17, 'You widen the centralizer spacing by a factor of two. Which term suffers most?', '["Doubles the centralizer deflection and multiplies the sag by sixteen.", "Doubles both of them.", "Doubles the deflection and quadruples the sag, since the sag depends on the square of the span rather than on its fourth power.", "Quadruples the deflection and multiplies the sag by sixteen, since both terms carry the span more than once."]'::jsonb, 0, 'The two cross around 9 m on this casing, and after that the sag runs away.'),
  ('cementing', 'advanced', 'final', null, 18, 'Which buys more on the horizontal well, 12 m to 9 m or 8900 N to 17800 N?', '["The spring, since it acts at the centralizer directly.", "They are comparable, since both halve the deflection and the sag responds to the load in the same way that the deflection does.", "The spacing, at 0.8065003150066353 against 0.6760682186894637 from the base of 0.599178961025609.", "The spacing: 21 points against 8, because the spring does nothing at all to the sag."]'::jsonb, 3, 'One buys 21 points and one buys 8, and the second is usually the more expensive.'),
  ('cementing', 'advanced', 'final', null, 19, 'Where does the standoff reaching exactly zero come from?', '["The centralizer bottoming out against the wall.", "The clamp in the code, which limits the reported standoff to zero rather than letting the formula return a negative value.", "The sag reaching the whole clearance, at 17.021127200569346 m at 90 degrees.", "The sag reaching the clearance, which needs a spacing of about seventeen metres at ninety degrees on this casing."]'::jsonb, 2, 'The centralizer would need a spacing of 78.03430781229383 m at 90 degrees to bottom out.'),
  ('cementing', 'advanced', 'final', null, 20, 'The two wells hit zero standoff at different spacings. What sets the ratio?', '["The ratio of the two sines directly.", "The fourth root of the ratio of the two sines, because the sag is quartic in the span.", "The ratio of the two clearances, since the wells are drilled with different bits and their open hole sections differ in size.", "The square root of the ratio of the two buoyed weights, which differ because the two wells are cemented in different muds."]'::jsonb, 1, '19.009532790549464 over 17.021127200569346 is 1.1168.'),
  ('cementing', 'advanced', 'final', null, 21, 'The mud weight is raised from 1030 to 2000. What does the standoff do?', '["Buoyancy reduces the lateral load, and the whole realistic range is worth about six points on the horizontal well.", "It does not; heavier mud makes everything harder.", "Because a denser fluid supports the pipe hydrodynamically, and the effect is worth about twenty points over the same range.", "Because the buoyancy factor multiplies the clearance rather than the weight, so the effective annulus widens with density."]'::jsonb, 0, 'Small compared with what spacing does, and worth knowing the sign of.'),
  ('cementing', 'advanced', 'final', null, 22, 'The required spacing routine returns null. What does that mean?', '["That the target was met at the widest spacing.", "That the bisection did not converge within its forty iterations, which happens when the function is not monotone.", "That the target cannot be reached with that device in that hole, which is a different conversation from a tight spacing.", "Not achievable: even the tightest spacing in the range misses the target."]'::jsonb, 3, 'Returning the tightest spacing instead would hide that case inside a design and the reader would run it and still fail.'),
  ('cementing', 'advanced', 'final', null, 23, 'What does the bisection assume, and is it true here?', '["That the function is linear, which it is not.", "That the target is reachable somewhere in the range, which the two guards check before the search starts and which holds here.", "That the minimum standoff falls monotonically with spacing, and yes, because both terms do.", "That the standoff is continuous in the spacing, which fails where the sag clamp engages and the reported value jumps to zero."]'::jsonb, 2, 'The spacing sweep shows the monotonicity directly.'),
  ('cementing', 'advanced', 'final', null, 24, 'Two wells, same centralizer programme at 12 m. What are their verdicts?', '["Both pass, since the required spacings exceed 12.", "The slant well passes at 0.742357202445576 and the horizontal one fails at 0.599178961025609.", "Both fail, since the required spacings of 13.05523892558449 and 11.187558579905271 metres straddle the twelve being run.", "The horizontal one passes because its clearance is smaller, and the slant one fails because its inclination is lower."]'::jsonb, 1, 'Their required spacings are 13.05523892558449 and 11.187558579905271.'),
  ('cementing', 'advanced', 'final', null, 25, 'A well 56 percent harder needs its centralizers how much closer?', '["About 17 percent, because the spacing scales as the fourth root of the inverse load.", "About 56 percent, in direct proportion.", "About 24 percent, which is the square root of the load ratio, since the sag is quadratic in the span at fixed stiffness.", "About 12 percent, since the centralizer deflection term partly compensates for the increase in the sag term."]'::jsonb, 0, 'The fourth power that made the problem steep also makes the remedy cheap.'),
  ('cementing', 'advanced', 'final', null, 26, 'You want a wide spacing up top and a tight one below. Can the routine give you that?', '["A null when the target is unachievable.", "The minimum standoff at the spacing it returns, which has to be recovered by running the profile again at that spacing.", "A spacing per interval, so a programme that is wide in the vertical and tight in the open hole has to be built by hand.", "A staged profile: it returns one number for the whole string, against the worst interval."]'::jsonb, 3, 'Both wells report a standoff of exactly 1 through their vertical sections.'),
  ('cementing', 'advanced', 'final', null, 27, 'The volume side and the standoff side use different bores. Which uses which?', '["Both use the nominal bore for consistency.", "The volume side the nominal bore and the standoff side the washed-out one, since the pipe sits in the hole as it actually is.", "The volume side the washed-out bore, and the standoff side the nominal one.", "The volume side the effective bore and the standoff side the drift of the previous casing above the open hole section."]'::jsonb, 2, 'The standoff call passes an excess of zero explicitly.'),
  ('cementing', 'advanced', 'final', null, 28, 'The hole washed out and the calculation did not know. Which way is the reported number wrong?', '["Conservative, since a smaller bore means a tighter annulus.", "Optimistic, because a washed-out hole gives the pipe more room to move off centre.", "Neither, since the sag becomes a smaller fraction of a larger clearance and the two effects cancel almost exactly out.", "It depends on the device, being optimistic for a bow spring and conservative for a rigid blade in a washed-out hole."]'::jsonb, 1, 'It is much worse for a rigid centralizer, whose standoff is a pure ratio of diameters.'),
  ('cementing', 'advanced', 'final', null, 29, 'Name three of the five omissions from the standoff calculation.', '["Tension times dogleg, casing movement, and the pipe''s own residual curvature.", "The clearance, the inclination and the buoyancy.", "The bending stiffness, the restoring force and the spacing, all three of which have to be supplied by the caller rather than computed.", "Contamination, thickening time and gas migration, which are the three chemistry omissions the whole course carries."]'::jsonb, 0, 'Cuttings beds and the centralizers'' own running drag are the other two.'),
  ('cementing', 'advanced', 'final', null, 30, 'Are the five missing effects conservative, taken together?', '["All optimistic, so the answer is an upper bound.", "All conservative, so a job that passes on the reported number passes on the real one with margin left over as well.", "Tension times dogleg makes it worse, cuttings beds make it better, and residual curvature could go either way.", "Not all the same way, which is the least comfortable kind of approximation."]'::jsonb, 3, 'Which is why the number is not conservative in a stated direction.'),
  ('cementing', 'advanced', 'final', null, 31, 'Tripling the restoring force on the horizontal well reaches 0.7016979712440818. What does that tell you?', '["That the spring lever is as good as the spacing lever.", "That the centralizer deflection had been the binding term all along, and that a stronger spring is therefore the right answer.", "It only just reaches the target, and the sag-only ceiling at that spacing is 0.7529574763533182.", "That the API target can always be reached by a strong enough centralizer, at any spacing, on any well."]'::jsonb, 2, 'Past about 18000 N the whole standoff is sag and the spring has stopped mattering.'),
  ('cementing', 'advanced', 'final', null, 32, 'Before choosing a centralizer, which number should you work out first?', '["The standoff at the tightest achievable spacing.", "One less the sag over the clearance, and before choosing a centralizer at all.", "The standoff a rigid blade equal to the bore would give, which is the theoretical best for that hole size and casing.", "One less the sag over the clearance, computed at the spacing you intend to run, which caps what any spring can achieve."]'::jsonb, 1, 'If it is below your target, no centralizer will do and the spacing has to come down.'),
  ('cementing', 'advanced', 'final', null, 33, 'Which checklist item can be absent, and why does that matter?', '["The standoff, if no centralizer is supplied.", "The free-fall item, since it needs a pump rate and a run made only to compute volumes would not supply one to the routine.", "The annular velocity, which needs both the annulus rows and a pump rate, and the engine''s own test asserts at least five.", "The annular velocity, so the total can be four and a caller comparing against a hard-coded five would be wrong."]'::jsonb, 3, 'It is added inside a conditional in the checklist function.'),
  ('cementing', 'advanced', 'final', null, 34, 'The horizontal well''s slowest annular velocity is 1.476222714457212 m/s. Where?', '["In the cased section above the previous shoe.", "In the open hole, because an 8-1/2 inch bit drills a smaller hole than the casing above and a smaller annulus is slower.", "In the washed-out open hole, which the excess made the wider and therefore the slower of the two annuli.", "At the shoe, where the annulus narrows into the shoe track and the velocity rises to its maximum for the whole string."]'::jsonb, 2, 'At the bit size the open hole would have been the faster of the two.'),
  ('cementing', 'advanced', 'final', null, 35, 'Did the mud removal velocity criterion constrain the rate on either of these two wells?', '["Yes, it is what set the design rate.", "No. Both velocities are about five times it, and neither constrained the rate choice.", "Yes on the horizontal well, whose longer annulus gives a lower velocity at the same rate, and no on the slant one.", "It cannot be said, since the target is a screening value with no defensible basis to compare an actual velocity against."]'::jsonb, 1, 'It stops being slack on a large-diameter surface casing in a washed-out hole.'),
  ('cementing', 'advanced', 'final', null, 36, 'Three constraints act on the pump rate. How do they divide?', '["Free fall and mud removal, against the fracture limit at the previous shoe.", "Free fall and the fracture limit, against mud removal.", "Mud removal and the thickening time, since a faster job finishes sooner and leaves more margin against the slurry setting up.", "The fracture limit and mud removal, since both improve at higher rates while free fall is unaffected by the rate."]'::jsonb, 0, 'Two constraints want it high and one wants it low.'),
  ('cementing', 'advanced', 'final', null, 37, 'Competing software returns a job quality percentage. Why does this one not?', '["Because the calculation would be too expensive.", "Because the API specification does not define one, so any number reported would not be comparable between operators.", "Because the weights are unmeasured, the score conceals which of the five items failed, and it can never be falsified.", "The weights would be invented, a score hides which item failed, and no field measurement returns a percentage."]'::jsonb, 3, 'The engine''s own comment calls it honest, not a fake efficiency percentage.'),
  ('cementing', 'advanced', 'final', null, 38, 'Of the four objections to a weighted score, which one actually costs something?', '["It is harder to compute than five booleans.", "It cannot be compared between jobs, since the weighting depends on the geometry and every job would weight the items differently.", "It sounds like a measurement, and travels into reports with that implication attached.", "It encourages the designer to optimise the score, which is a different objective from isolating the reservoir."]'::jsonb, 2, 'A list of five booleans carries no such implication.'),
  ('cementing', 'advanced', 'final', null, 39, 'This tier teaches nine things and grades none of them. Name three.', '["Standoff, annular velocity and the required spacing.", "Casing rotation, intermixing, and cement bond evaluation.", "The lateral load, the spring rate and the mid-span sag, all three of which are inputs to the graded standoff rather than outputs.", "The clearance, the buoyancy factor and the bending stiffness, which the capstone supplies rather than asking for."]'::jsonb, 1, 'Thickening time, temperature, losses, gas migration, the transient free-fall rate and tension times dogleg are the others.'),
  ('cementing', 'advanced', 'final', null, 40, 'The go-live migration refuses a capstone field named what?', '["Anything matching rotation, contamination, thickening, temperature, losses, gas migration, bond or a free-fall rate.", "Anything with a unit of kilograms per cubic metre.", "Anything whose expected value falls within tolerance of a number the published goldens carry, which would make it a lookup.", "Anything whose tolerance is zero or negative, since a graded field has to be checkable against a stated precision."]'::jsonb, 0, 'A scope decision written as a check, so a later edit that added one is stopped rather than reviewed.'),
  ('cementing', 'advanced', 'final', null, 41, 'What are the four things that decide whether a cement job worked?', '["Volumes, placement, standoff and chemistry.", "The excess, the fluid programme, the pump rate and the centralizer spacing, which are the four decisions this course makes.", "Whether the slurry set, whether it bonded, whether the mud left, and whether the well was isolated, and this course computes none.", "Whether the cement set, bonded, displaced the mud, and isolated the well."]'::jsonb, 3, 'This course makes the decisions that CAN be made before the job.'),
  ('cementing', 'advanced', 'final', null, 42, 'What is the transferable habit across all three tiers of this course?', '["Compute every number to fifteen significant figures.", "Never report a result without the engine version string attached, so that it can be traced back to the code that made it.", "Find out which number the answer actually depends on, before spending effort on the others.", "Always bias an uncertain input in the conservative direction, and state which direction that was in the report."]'::jsonb, 2, 'Write the excess next to the volume, bisect the edge, compute the sag before choosing the centralizer.');
